import json
import itertools

def solve():
    houses = [1, 2, 3]  # left to right
    Names = ["Eric", "Peter", "Arnold"]
    Mothers = ["Holly", "Aniya", "Janelle"]
    Lunches = ["pizza", "grilled cheese", "spaghetti"]

    for names in itertools.permutations(Names):
        # Clue 4: Peter is The person whose mother's name is Holly.
        # We'll enforce this after choosing mothers
        for mothers in itertools.permutations(Mothers):
            # Enforce clue 4 early where possible
            try:
                idx_peter = names.index("Peter")
                if mothers[idx_peter] != "Holly":
                    continue
            except ValueError:
                continue

            for lunches in itertools.permutations(Lunches):
                # Clue 3: The person who loves eating grilled cheese is Eric.
                idx_grilled = lunches.index("grilled cheese")
                if names[idx_grilled] != "Eric":
                    continue

                # Clue 2: The grilled cheese eater is directly left of the person whose mother's name is Aniya.
                idx_aniya = mothers.index("Aniya")
                if idx_grilled + 1 != idx_aniya:
                    continue

                # Clue 1 (interpreted): The spaghetti eater and Peter are next to each other.
                idx_spaghetti = lunches.index("spaghetti")
                if abs(idx_spaghetti - idx_peter) != 1:
                    continue

                # All constraints satisfied
                solution_rows = []
                for i, house in enumerate(houses):
                    solution_rows.append([
                        str(house),
                        names[i],
                        mothers[i],
                        lunches[i],
                    ])
                header = ["House", "Name", "Mother", "Lunch"]
                return {
                    "solution": {
                        "header": header,
                        "rows": solution_rows
                    }
                }

    return {"solution": {"header": ["House", "Name", "Mother", "Lunch"], "rows": []}}

if __name__ == "__main__":
    result = solve()
    print(json.dumps(result, ensure_ascii=False))
